export function getFallbackModels(brand: string): FacetItem[] {
  if (!brand) return [];
  const upper = brand.toUpperCase().trim();
  return FALLBACK_MODELS_MAP[upper] ?? [
    { value: upper + ' 1.5', label: upper + ' 1.5' },
    { value: upper + ' 2.0', label: upper + ' 2.0' }
  ];
}

